-- CTF DS 3.2.0 — catálogo oficial AGV Core
create unique index if not exists reward_rules_rule_key_idx on public.reward_rules(platform_id, coalesce(activity_id,''), event_type);

on conflict (platform_id,activity_id) do update set name=excluded.name,reward_policy=excluded.reward_policy,max_xp=excluded.max_xp,max_points=excluded.max_points,max_coins=excluded.max_coins,repeatable=excluded.repeatable,daily_limit=excluded.daily_limit,active=true,metadata=excluded.metadata,updated_at=now();

on conflict do nothing;
